import { KpiContent } from '../types';

export const EMPTY_KPI_CONTENT: KpiContent = {
  labels: [],
  datasets: [],
  total_allocation: { value: [] },
  caption_country_flag: {},
};

export const normalizeKpiContent = (kpiContent?: KpiContent): KpiContent => {
  if (!kpiContent || !Array.isArray(kpiContent.labels)) {
    return EMPTY_KPI_CONTENT;
  }

  return kpiContent;
};
